bool CapsuleSweepIntersection(const Capsule_t& capsule, const Vector& start, const Vector& delta, SweepHit_t* hit) {
    Vector segA = capsule.m_vCenter0, segB = capsule.m_vCenter1;
    float radius = capsule.m_flRadius;
    float tRay, tSeg;
    ClosestSegmentSegment(start, start + delta, segA, segB, &tRay, &tSeg);
    Vector ptRay = start + delta * tRay;
    Vector ptSeg = segA + (segB - segA) * tSeg;
    if ((ptRay - ptSeg).LengthSqr() <= radius * radius) {
        hit->fraction = tRay;
        hit->normal = (ptRay - ptSeg).Normalized();
        return true;
    }
    return false;
}

bool CTwoBoneIK_LawOfCosines(float l1, float l2, float targetDist, float* outAngleA, float* outAngleB) {
    // Law of Cosines: c^2 = a^2 + b^2 - 2ab * cos(C)
    float clampedDist = std::clamp(targetDist, std::abs(l1 - l2) + 0.001f, (l1 + l2) - 0.001f);
    float cosB = (l1 * l1 + l2 * l2 - clampedDist * clampedDist) / (2.0f * l1 * l2);
    float cosA = (l1 * l1 + clampedDist * clampedDist - l2 * l2) / (2.0f * l1 * clampedDist);
    *outAngleB = std::acos(std::clamp(cosB, -1.0f, 1.0f)); // Knee / Elbow bend
    *outAngleA = std::acos(std::clamp(cosA, -1.0f, 1.0f)); // Shoulder / Hip bend
    return true;
}

bool EvaluateBulletPenetration(BulletData_t& bullet, const SurfaceHitData_t& hit, bool ffBulletPenetration) {
    if (!(hit.flags & 1)) {
        float dist = (hit.tExit - hit.tEnter) * bullet.maxRange;
        bullet.currentDamage *= std::pow(bullet.rangeModifier, dist / 500.0f);
        return true;
    }
    float penMod = hit.enterSurface.bulletPenetrationDistanceModifier;
    if (hit.tExit * bullet.maxRange > 3000.0f || penMod < 0.1f || bullet.penetrationCount < 1) return false;
    float thickness = (hit.exitPoint - hit.enterPoint).Length();
    float penModInv = std::max(0.0f, 1.0f / penMod);
    float lostDist = (thickness * thickness * penModInv) / 24.0f;
    float lostEntry = std::max(0.0f, (3.0f / bullet.penetrationPower) * 1.25f) * (penModInv * 3.0f) + (0.16f * bullet.currentDamage);
    bullet.currentDamage -= (lostDist + lostEntry);
    if (bullet.currentDamage < 1.0f) return false;
    bullet.penetrationCount--;
    return true;
}

