void C_CSWeaponBase::UpdateAccuracyPenalty() {
    float target = GetTargetInaccuracy();
    if (m_fAccuracyPenalty >= target) {
        float recoveryTime = GetRecoveryTime();
        float decay = std::exp(-(std::log(10.0f) / recoveryTime) * dt);
        m_fAccuracyPenalty = target + (m_fAccuracyPenalty - target) * decay;
    } else {
        m_fAccuracyPenalty = target;
    }
    UpdateTurningInaccuracy();
    if (m_flRecoilIndex > 0.0f && curTime - m_fLastShotTime > m_flCycleTime + dt) {
        m_flRecoilIndex *= std::exp(-2.0f * std::log(10.0f) * dt);
        if (m_flRecoilIndex <= 0.1f) m_flRecoilIndex = 0.0f;
    }
}

void CPlayer_AimPunchServices::SimulateAimPunchDecay(float dt) {
    float velDamping = std::exp(-4.5f * dt);
    m_aimPunchAngleVel *= velDamping;
    m_aimPunchAngle += m_aimPunchAngleVel * dt;
    float magSqr = m_aimPunchAngle.LengthSqr();
    if (magSqr <= 0.140625f) {
        m_aimPunchAngle.Init();
        m_aimPunchAngleVel.Init();
    } else {
        m_aimPunchAngle *= (1.0f - 0.140625f / magSqr);
    }
    m_aimPunchAngle.pitch = std::clamp(m_aimPunchAngle.pitch, -89.0f, 89.0f);
}

void CPlayerMovement::WalkMove(PlayerMovementServices& services, PlayerMoveData& mv, float dt) {
    services.m_bHasWalkMovedSinceLastJump = true;
    QAngle moveAngles{0.0f, mv.viewAngles.y, 0.0f};
    Vector3 forward, right, up;
    CViewRender::AngleVectors(moveAngles, &forward, &right, &up);
    Vector3 wishvel = forward * mv.forwardMove + right * mv.sideMove;
    float wishspeed = wishvel.Length2D();
    Vector3 wishdir = (wishspeed > 0.0f) ? wishvel / wishspeed : Vector3{};
    wishspeed = std::min(wishspeed, mv.maxSpeed);
    Friction(services, mv, dt);
    Accelerate(services, mv, wishdir, wishspeed, SV_ACCELERATE, dt);
    mv.velocity.z = 0.0f;
    StepMove(services, mv, dt);
    CategorizePosition(services, mv, dt);
}

void CPlayerMovement::AirAccelerate(PlayerMovementServices& services, PlayerMoveData& mv, const Vector3& wishdir, float wishspeed, float accel, float dt) {
    const float wishspd = std::min(wishspeed, SV_AIR_MAX_WISHSPEED);
    const float currentspeed = DotProduct(mv.velocity, wishdir);
    const float addspeed = wishspd - currentspeed;
    if (addspeed <= 0.0f) return;
    float accelspeed = accel * wishspeed * dt * services.m_flSurfaceFriction;
    if (accelspeed > addspeed) accelspeed = addspeed;
    mv.velocity += wishdir * accelspeed;
}

bool CSubtickMoveStep::_InternalParse(CByteStreamReader& reader) {
    while (reader.HasMore()) {
        uint32_t tag;
        if (!reader.ReadVarInt32(tag)) return false;
        uint32_t fieldNumber = tag >> 3;
        WireType wireType = static_cast<WireType>(tag & 7);
        switch (fieldNumber) {
            case 1: if (!reader.ReadVarInt64(m_nButton)) return false; m_nHasBits |= HAS_BUTTON; break;
            case 2: uint32_t val; if (!reader.ReadVarInt32(val)) return false; m_bPressed = (val != 0); m_nHasBits |= HAS_PRESSED; break;
            case 3: if (!reader.ReadFloat(m_flWhen)) return false; m_flWhen = std::clamp(m_flWhen, 0.0f, 1.0f); m_nHasBits |= HAS_WHEN; break;
            case 4: if (!reader.ReadFloat(m_flAnalogForwardDelta)) return false; m_nHasBits |= HAS_ANALOG_FORWARD_DELTA; break;
            case 5: if (!reader.ReadFloat(m_flAnalogLeftDelta)) return false; m_nHasBits |= HAS_ANALOG_LEFT_DELTA; break;
            default: if (!reader.SkipField(wireType)) return false; break;
        }
    }
    return true;
}

void CBaseUserCmdPB::_InternalSerialize(CByteStreamWriter& writer) const {
    if (m_nHasBits & HAS_COMMAND_NUMBER) { writer.WriteTag(1, WireType::VarInt); writer.WriteVarInt32(m_nCommandNumber); }
    if (m_nHasBits & HAS_CLIENT_TICK) { writer.WriteTag(2, WireType::VarInt); writer.WriteVarInt32(m_nClientTick); }
    for (const auto& step : m_SubtickMoves) {
        CByteStreamWriter stepWriter;
        step._InternalSerialize(stepWriter);
        writer.WriteTag(18, WireType::LengthDelimited); // Tag bytes: 0x92 0x01
        writer.WriteLengthDelimited(stepWriter.GetData().data(), stepWriter.GetSize());
    }
}

