float C_CSWeaponBase::GetInaccuracy(float* outSpread, float* outJumpInacc) {
    float total = m_fAccuracyPenalty;
    float speed2D = std::sqrt(vel.x * vel.x + vel.y * vel.y);
    float low = m_flMaxSpeed * 0.34f, high = m_flMaxSpeed * 0.95f;
    if (speed2D > low) {
        float frac = std::clamp((speed2D - low) / (high - low), 0.0f, 1.0f);
        if (ducking) frac = std::pow(frac, 0.25f);
        total += frac * m_flInaccuracyMove;
    }
    if (!onGround) total += GetJumpInaccuracy();
    total += CalculateStrafingInaccuracy() + m_flTurningInaccuracy;
    return std::clamp(total, 0.0f, 1.0f);
}

void FX_CalculateSpread(uint16_t itemDefIndex, int32_t numBullets, int32_t weaponMode, int32_t seed, float inacc, float spread, float recoilIdx, float* outX, float* outY) {
    RandomSeed(seed);
    float r1 = RandomFloat(0.0f, 1.0f), theta1 = RandomFloat(0.0f, 2.0f * PI);
    if (itemDefIndex == 64 && weaponMode == 1) r1 = 1.0f - r1 * r1;
    float R_inacc = r1 * inacc;
    float r2 = RandomFloat(0.0f, 1.0f), theta2 = RandomFloat(0.0f, 2.0f * PI);
    if (itemDefIndex == 64 && weaponMode == 1) r2 = 1.0f - r2 * r2;
    float R_spread = r2 * spread;
    *outX = std::cos(theta1) * R_inacc + std::cos(theta2) * R_spread;
    *outY = std::sin(theta1) * R_inacc + std::sin(theta2) * R_spread;
}

void CLagCompensationManager::FinishLagCompensation() {
    if (!this->m_bLagCompensationActive || !this->m_bNeedRestore) return;
    for (int i = 0; i < this->m_nTrackedPawnCount; ++i) {
        TrackedEntity_t* entry = &this->m_pTrackedPawns[i];
        if (!entry->m_bIsBacktracked) continue;
        CBaseEntity* entity = ResolveEntityHandle(entry->m_hEntity);
        if (entity && entry->m_pRestoreRecord) {
            RestoreEntityTo(entity, entry->m_pRestoreRecord);
        }
        entry->m_bIsBacktracked = false;
    }
    this->m_bLagCompensationActive = false;
}

void CLagCompensationManager::RestoreEntityTo(CBaseEntity* entity, const LagRecord_t* record) {
    if (record->flags & LAG_RECORD_BOUNDS_CHANGED) entity->SetCollisionBounds(record->mins, record->maxs);
    if (record->flags & LAG_RECORD_ANGLES_CHANGED) entity->SetEyeAngles(record->eyeAngles);
    if (record->flags & LAG_RECORD_ORIGIN_CHANGED) {
        float distSqr = (entity->GetAbsOrigin() - record->preTeleportOrigin).LengthSqr();
        if (distSqr < 4096.0f) entity->SetAbsOrigin(record->origin);
    }
    if (record->flags & LAG_RECORD_BONES_CHANGED) entity->SetupBones(record->boneMatrices, record->boneCount);
}

