bool CCSPlayerPawn::IsArmored(HitGroup_t hitGroup) const {
    if (m_ArmorValue <= 0) return false;
    switch (hitGroup) {
        case HITGROUP_GENERIC: case HITGROUP_CHEST: case HITGROUP_STOMACH:
        case HITGROUP_LEFTARM: case HITGROUP_RIGHTARM:
            return true;
        case HITGROUP_HEAD: case HITGROUP_NECK:
            return m_pItemServices && m_pItemServices->m_bHasHelmet;
        default:
            return false;
    }
}

std::pair<ChildWeight, ChildWeight> CBlendUpdateNode_ComputeWeights(float blendValue, int numChildren) {
    if (numChildren <= 1) return {{0, 1.0f}, {-1, 0.0f}};
    float clamped = std::clamp(blendValue, 0.0f, static_cast<float>(numChildren - 1));
    int base = static_cast<int>(std::floor(clamped));
    float frac = clamped - static_cast<float>(base);
    return {{base, 1.0f - frac}, {base + 1, frac}};
}

