Quaternion Quaternion::FromAngleAxis(const Vector3& axis, float angleRad) {
    float s = std::sin(angleRad * 0.5f);
    Vector3 norm = axis.Normalized();
    return {norm.x * s, norm.y * s, norm.z * s, std::cos(angleRad * 0.5f)};
}
